using System.Collections;

namespace Gori.StaticInstances.Testing.TestData;

public class CombinedGenerator_TestData : IEnumerable<TheoryDataRow<ISimpleTestData>>
{
    public const string TestPrefix = "Combined";

    public const string Category = "Generator\\Combined";

    public const string DefaultExpected =
        """
        // <auto-generated/>
        #nullable enable
        partial class MyService
        {
            public static MyService Instance { get; } = new MyService();
            public static MyService MyInstance { get; } = new MyService();
        }
        """;

    public IEnumerator<TheoryDataRow<ISimpleTestData>> GetEnumerator()
    {
        // -------------------------------------------------------------------------
        // Default behavior, no options
        // -------------------------------------------------------------------------

        string prefix = $"{TestPrefix} Default Behavior";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                [method: StaticInstance(Name = "MyInstance")]
                public partial class MyService () { }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class primary constructor",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                [method: StaticInstance(Name = "MyInstance")]
                public partial class MyService ()
                {
                    static MyService() { }
                }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Class with primary constructor and static constructor",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService
                {
                    [StaticInstance(Name = "MyInstance")]
                    private MyService () { }
                }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Existing private default constructor",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService
                {
                    [StaticInstance(Name = "MyInstance")]
                    public MyService (int value) { }
                }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category, "Would Fail to Compile but Expected"] } },
            Label = $"{prefix}: Existing public constructor with parameters",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                [method: StaticInstance(Name = "MyInstance")]
                public partial class MyService<T> () { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService<T>
                {
                    public static MyService<T> Instance { get; } = new MyService<T>();
                    public static MyService<T> MyInstance { get; } = new MyService<T>();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Generic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                namespace My.App
                {
                    [Singleton]
                    [method: StaticInstance(Name = "MyInstance")]
                    public partial class MyService () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                namespace My.App
                {
                    partial class MyService
                    {
                        public static MyService Instance { get; } = new MyService();
                        public static MyService MyInstance { get; } = new MyService();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class in namespace",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer
                {
                    [Singleton]
                    [method: StaticInstance(Name = "MyInstance")]
                    public partial class Inner () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer
                {
                    partial class Inner
                    {
                        public static Inner Instance { get; } = new Inner();
                        public static Inner MyInstance { get; } = new Inner();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class nested inside basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class GrandParent
                {
                    public partial class Parent
                    {
                        [Singleton]
                        [method: StaticInstance(Name = "MyInstance")]
                        public partial class Child () { }
                    }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class GrandParent
                {
                    partial class Parent
                    {
                        partial class Child
                        {
                            public static Child Instance { get; } = new Child();
                            public static Child MyInstance { get; } = new Child();
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class deeply nested inside basic classes",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer<T>
                {
                    [Singleton]
                    [method: StaticInstance(Name = "MyInstance")]
                    public partial class Inner () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer<T>
                {
                    partial class Inner
                    {
                        public static Inner Instance { get; } = new Inner();
                        public static Inner MyInstance { get; } = new Inner();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class nested inside generic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer
                {
                    [Singleton]
                    [method: StaticInstance(Name = "MyInstance")]
                    public partial class Inner<T> () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer
                {
                    partial class Inner<T>
                    {
                        public static Inner<T> Instance { get; } = new Inner<T>();
                        public static Inner<T> MyInstance { get; } = new Inner<T>();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Generic class nested inside basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer<TKey>
                {
                    [Singleton]
                    [method: StaticInstance(Name = "MyInstance")]
                    public partial class Inner<TValue> () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer<TKey>
                {
                    partial class Inner<TValue>
                    {
                        public static Inner<TValue> Instance { get; } = new Inner<TValue>();
                        public static Inner<TValue> MyInstance { get; } = new Inner<TValue>();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Generic class nested inside generic class",
        };

        // -------------------------------------------------------------------------
        // Single option behaviors - Type
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Type";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Property)]
                [method: StaticInstance(Name = "MyInstance", Type = InstanceType.Property)]
                public partial class MyService () { }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Default (Property): Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Weak)]
                [method: StaticInstance(Name = "MyInstance", Type = InstanceType.Weak)]
                public partial class MyService () { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                #if NET9_0_OR_GREATER
                    private static readonly Lock _weakLock = new Lock();
                #else
                    private static readonly object _weakLock = new object();
                #endif
                
                    private static readonly WeakReference<MyService> _instance = new WeakReference<MyService>(null!);

                    public static MyService Instance
                    {
                        get
                        {
                            if (_instance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            lock(_weakLock)
                            {
                                if (_instance.TryGetTarget(out currentInstance))
                                {
                                    return currentInstance;
                                }

                                currentInstance = new MyService();
                                _instance.SetTarget(currentInstance);
                                return currentInstance;
                            }
                        }
                    }

                    private static readonly WeakReference<MyService> _myInstance = new WeakReference<MyService>(null!);
                
                    public static MyService MyInstance
                    {
                        get
                        {
                            if (_myInstance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }
                
                            lock(_weakLock)
                            {
                                if (_myInstance.TryGetTarget(out currentInstance))
                                {
                                    return currentInstance;
                                }
                
                                currentInstance = new MyService();
                                _myInstance.SetTarget(currentInstance);
                                return currentInstance;
                            }
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Weak: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.WeakLockless)]
                [method: StaticInstance(Name = "MyInstance", Type = InstanceType.WeakLockless)]
                public partial class MyService () { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    private static readonly WeakReference<MyService> _instance = new WeakReference<MyService>(null!);

                    public static MyService Instance
                    {
                        get
                        {
                            if (_instance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            currentInstance = new MyService();
                            _instance.SetTarget(currentInstance);
                            return currentInstance;
                        }
                    }
                
                    private static readonly WeakReference<MyService> _myInstance = new WeakReference<MyService>(null!);
                
                    public static MyService MyInstance
                    {
                        get
                        {
                            if (_myInstance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }
                
                            currentInstance = new MyService();
                            _myInstance.SetTarget(currentInstance);
                            return currentInstance;
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = WeakLockless: Basic class",
        };

        // -------------------------------------------------------------------------
        // Mixture of different options together
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Mixed Bag";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.WeakLockless)]
                public partial class MyService
                {
                    [StaticInstance(Name = "MyInstance1", Type = InstanceType.Property)]
                    public MyService () { }
                    [StaticInstance(2, Name = "MyInstance2", Type = InstanceType.Weak)]
                    public MyService (int value) { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                #if NET9_0_OR_GREATER
                    private static readonly Lock _weakLock = new Lock();
                #else
                    private static readonly object _weakLock = new object();
                #endif
                
                    private static readonly WeakReference<MyService> _instance = new WeakReference<MyService>(null!);

                    public static MyService Instance
                    {
                        get
                        {
                            if (_instance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            currentInstance = new MyService();
                            _instance.SetTarget(currentInstance);
                            return currentInstance;
                        }
                    }
                        
                    public static MyService MyInstance1 { get; } = new MyService();

                    private static readonly WeakReference<MyService> _myInstance2 = new WeakReference<MyService>(null!);
                
                    public static MyService MyInstance2
                    {
                        get
                        {
                            if (_myInstance2.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }
                
                            lock(_weakLock)
                            {
                                if (_myInstance2.TryGetTarget(out currentInstance))
                                {
                                    return currentInstance;
                                }
                
                                currentInstance = new MyService(2);
                                _myInstance2.SetTarget(currentInstance);
                                return currentInstance;
                            }
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class GrandParent
                {
                    public partial class Parent
                    {
                        [StaticInstance(Name = "MyInstance")]
                        public Parent () { }
                        [Singleton]
                        public partial class Child
                        {
                            [StaticInstance(Name = "MyInstance")]
                            public Child () { }
                        }
                    }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class GrandParent
                {
                    private GrandParent () { }

                    public static GrandParent Instance { get; } = new GrandParent();
                }
                // <auto-generated/>
                #nullable enable

                partial class GrandParent
                {
                    partial class Parent
                    {
                        partial class Child
                        {
                            public static Child Instance { get; } = new Child();

                            public static Child MyInstance { get; } = new Child();
                        }
                    }
                }
                // <auto-generated/>
                #nullable enable

                partial class GrandParent
                {
                    partial class Parent
                    {
                        public static Parent MyInstance { get; } = new Parent();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class deeply nested inside basic classes",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService1 { }

                [Singleton]
                public partial class MyService2 () { }
                
                public partial class MyService3
                {
                    [StaticInstance(Name = "MyInstance")]
                    public MyService3() { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService1
                {
                    private MyService1 () { }

                    public static MyService1 Instance { get; } = new MyService1();
                }
                // <auto-generated/>
                #nullable enable

                partial class MyService2
                {
                    public static MyService2 Instance { get; } = new MyService2();
                }
                // <auto-generated/>
                #nullable enable

                partial class MyService3
                {
                    public static MyService3 MyInstance { get; } = new MyService3();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class (multiple in single file)",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Lazy)]
                public partial class GrandParent
                {
                    public class ParentBase 
                    {
                        protected object _weakLock = null!;
                        private void _myInstance() { }
                    }
                    public partial class Parent : ParentBase
                    {
                        private string _myInstance { get; } = null!;
                        [StaticInstance(Name = "MyInstance", Type = InstanceType.Weak)]
                        public Parent () { }
                        [Singleton]
                        public partial class Child : ParentBase
                        {
                            [StaticInstance(Name = "MyInstance", Type = InstanceType.WeakLockless)]
                            public Child () { }
                        }
                    }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class GrandParent
                {
                    private GrandParent () { }
                    private static readonly Lazy<GrandParent> _instance = new Lazy<GrandParent>(() => new GrandParent());
                    public static GrandParent Instance => _instance.Value;
                }
                // <auto-generated/>
                #nullable enable
                partial class GrandParent
                {
                    partial class Parent
                    {
                        partial class Child
                        {
                            public static Child Instance { get; } = new Child();
                            private static readonly WeakReference<Child> _myInstance = new WeakReference<Child>(null!);
                            public static Child MyInstance
                            {
                                get
                                {
                                    if (_myInstance.TryGetTarget(out Child? currentInstance))
                                    {
                                        return currentInstance;
                                    }
                                    currentInstance = new Child();
                                    _myInstance.SetTarget(currentInstance);
                                    return currentInstance;
                                }
                            }
                        }
                    }
                }
                // <auto-generated/>
                #nullable enable
                partial class GrandParent
                {
                    partial class Parent
                    {
                #if NET9_0_OR_GREATER
                        private static readonly Lock _weakLock1 = new Lock();
                #else
                        private static readonly object _weakLock1 = new object();
                #endif
                        private static readonly WeakReference<Parent> _myInstance1 = new WeakReference<Parent>(null!);
                        public static Parent MyInstance
                        {
                            get
                            {
                                if (_myInstance1.TryGetTarget(out Parent? currentInstance))
                                {
                                    return currentInstance;
                                }
                                lock(_weakLock1)
                                {
                                    if (_myInstance1.TryGetTarget(out currentInstance))
                                    {
                                        return currentInstance;
                                    }

                                    currentInstance = new Parent();
                                    _myInstance1.SetTarget(currentInstance);
                                    return currentInstance;
                                }
                            }
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class deeply nested inside basic classes, with field name conflicts",
        };
    }

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}
